#!/usr/bin/env python3
"""Capture tests/fixtures/toolchain_exec_key/reference_receipt.json with genuine Bazel.

Usage: capture.py --bazel /path/to/bazel-9.3.1 --scratch DIR > reference_receipt.json

B13c (docs/OSS_CORPUS.md): one toolchain implementation resolved for two
execution platforms in one configuration. Genuine keys the implementation's
configured target by its parent's execution platform
(ConfiguredTargetKey.executionPlatformLabel), so both copies exist: their own
exec-configured tools, actions and outputs, two cquery results and two
aquery actions. Each case runs once in a fresh copy of workspace/ (--batch,
no rc files, private HOME and output user root) and records the exit code,
the stdout, the stderr lines matching the case's patterns (the workspace
path replaced by <WS>) and the content of the named outputs by their path
below bazel-out. tests/toolchain_exec_key.rs replays the cases natively.
"""

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
FLAGS = ['--platforms=//:p', '--host_platform=//:p',
         '--extra_execution_platforms=//tc:ea,//tc:eb']

# name: (command, extra flags, targets, stderr patterns, outputs)
CASES = {
    # The toolchain for //tc:ea (the configuration's first execution
    # platform) and for //tc:eb: two stamps, each consumer sees its own.
    'build_two_exec_platforms': (
        'build', [], ['//tc:both'], [],
        ['ea.stamp', 'eb.stamp', 'use_a.txt', 'use_b.txt']),
    # Only //tc:eb (not the first platform): one copy, forced to //tc:eb.
    'build_second_exec_platform_only': (
        'build', [], ['//tc:use_b'], [], ['ea.stamp', 'eb.stamp', 'use_b.txt']),
    # The implementation requested as a top-level target too: its plain
    # copy (no forced platform) and the //tc:eb copy.
    'build_top_level_and_toolchain': (
        'build', [], ['//tc:impl', '//tc:use_b'], [], ['ea.stamp', 'eb.stamp', 'use_b.txt']),
    # An alias implementation: the alias is keyed by the platform, its
    # actual target (an attribute edge) is not: one unforced copy.
    'build_alias_implementation': (
        'build', [], ['//tc:alias_a', '//tc:alias_b'], [],
        ['ea.stamp', 'eb.stamp', 'alias_a.txt', 'alias_b.txt']),
    # Equal FileWrite actions of the two copies on two execution platforms
    # conflict (the execution platform is part of the action key).
    'build_copies_conflict': (
        'build', [], ['//tc:clash_a', '//tc:clash_b'],
        [r'is generated by these conflicting actions', r'^Label: '], []),
    # A genrule without toolchains whose context selects //tc:eb.
    'build_genrule_second_platform': (
        'build', [], ['//tc:gen_b'], [], ['gen_b.txt']),
    # A toolchain with an incoming rule transition to a configuration whose
    # first execution platform is //tc:eb: the //tc:eb delegate and that
    # configuration's own toolchain edge reach one configured target.
    'cquery_transitioned_toolchain': (
        'cquery', ['--output=label_kind'], ['filter("impl_t", deps(//tc:both_t))'], [], []),
    'cquery_two_results': (
        'cquery', ['--output=label_kind'], ['filter("impl", deps(//tc:both))'], [], []),
    'cquery_files': (
        'cquery', ['--output=files'], ['filter("impl", deps(//tc:both))'], [], []),
    'cquery_graph': (
        'cquery', ['--output=graph'], ['filter("impl", deps(//tc:both))'], [], []),
    'aquery_two_owners': (
        'aquery', [], ['mnemonic(Stamp, deps(//tc:both))'], [], []),
}

TIME = re.compile(r'^\(\d\d:\d\d:\d\d\) ')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--bazel', required=True)
    parser.add_argument('--scratch', required=True)
    args = parser.parse_args()
    scratch = os.path.abspath(args.scratch)
    shutil.rmtree(scratch, ignore_errors=True)
    cases = {}
    for index, (name, (command, extra, targets, patterns, outputs)) in enumerate(CASES.items()):
        root = os.path.join(scratch, str(index))
        workspace = os.path.join(root, 'ws')
        shutil.copytree(os.path.join(HERE, 'workspace'), workspace)
        home = os.path.join(root, 'home')
        os.makedirs(home)
        env = dict(PATH='/usr/bin:/bin', HOME=home, TMPDIR=home)
        flags = FLAGS + extra
        argv = ([args.bazel, '--batch', '--ignore_all_rc_files', f'--output_user_root={root}/our',
                 command] + flags + targets)
        result = subprocess.run(argv, cwd=workspace, env=env, capture_output=True, text=True)
        lines = [TIME.sub('(TIME) ', line.replace(workspace, '<WS>'))
                 for line in result.stderr.splitlines()]
        matched = []
        for pattern in patterns:
            found = [line for line in lines if re.search(pattern, line)]
            matched.append(dict(pattern=pattern, line=found[0] if found else None))
        files = {}
        out = os.path.join(workspace, 'bazel-out')
        for top, dirs, names in os.walk(out):
            dirs[:] = [d for d in dirs if not d.endswith('.runfiles')]
            for file in names:
                if file in outputs:
                    path = os.path.join(top, file)
                    files[os.path.relpath(path, out)] = open(path).read()
        cases[name] = dict(command=command, flags=flags, targets=targets,
                           exit=result.returncode, stdout=result.stdout, stderr=matched,
                           outputs=files)
    digest = hashlib.sha256(open(args.bazel, 'rb').read()).hexdigest()
    json.dump(dict(bazel='9.3.1', elf_sha256=digest, cases=cases), sys.stdout, indent=1,
              sort_keys=True)
    print()


if __name__ == '__main__':
    main()
